{
  "status": "NEEDS_IMPROVEMENT",
  "core_findings": [
    "Strong sampled training margins coexist with limited exact-catalog training-prefix HR@10: Movies 0.2083, Industrial 0, Electronics 0, and CDs 0.25. Sampled separation therefore does not establish strong catalog ranking or held-out performance.",
    "Permuting history worsens training-target ranks in Industrial and CDs, including when preserving the terminal item, indicating sensitivity to earlier ordering. Matched replacement effects have only one retained user in Movies and Electronics, so they cannot support broad recency conclusions."
  ],
  "key_implications": [
    "The model uses sequence order beyond the terminal item on the sampled Industrial and CDs prefixes.",
    "CDs’ large sampled margin does not establish broad competitor separation; embedding cosine scores alone do not establish collapse.",
    "These diagnostics provide no held-out performance estimate; pinned host macro validation HR@10 remains authoritative for selection."
  ],
  "evidence": {
    "headline_metrics": {
      "CDs_and_Vinyl:pos_neg_margin_mean": 15.7067,
      "CDs_and_Vinyl:training_prefix_hr10_user_mean": 0.25,
      "Industrial_and_Scientific:training_prefix_hr10_user_mean": 0.0,
      "Electronics:training_prefix_hr10_user_mean": 0.0,
      "Industrial_and_Scientific:terminal_preserving_permutation_delta_rank_mean": 716.6667,
      "CDs_and_Vinyl:terminal_preserving_permutation_delta_rank_mean": 985.4167
    },
    "brief_metric_read": {
      "pos_neg_margin_mean": "In-sample separation against sampled negatives, not catalog-wide ranking.",
      "training_prefix_hr10_user_mean": "Exact eligible-catalog training-target hits on selected users; not validation.",
      "terminal_preserving_permutation_delta_rank_mean": "Positive means worse target rank after reordering earlier history; each category includes 12 users.",
      "replacement_audit_support": "Movies retains one prefix/user; Electronics retains two prefixes from one user for displayed dose-one effects."
    }
  }
}
